def transform_fixed(grid):
    rows = len(grid)
    cols = len(grid[0])

    # Find background (most common value)
    all_vals = [grid[r][c] for r in range(rows) for c in range(cols)]
    counts = Counter(all_vals)
    background = counts.most_common(1)[0][0]

    # Find separator rows/cols (full of same value)
    sep_row_indices = []
    sep_col_indices = []

    for r in range(rows):
        if len(set(grid[r])) == 1:
            sep_row_indices.append(r)

    for c in range(cols):
        if len(set(grid[r][c] for r in range(rows))) == 1:
            sep_col_indices.append(c)

    # Get ranges between separators
    def get_ranges(sep_list, total):
        ranges = []
        start = 0
        for s in sorted(sep_list):
            if s > start and s < total:
                if start + 1 < total:
                    ranges.append((start, min(s-1, total-1)))
            start = s + 1
        if start < total:
            ranges.append((start, total-1))
        return ranges

    row_ranges = get_ranges(sep_row_indices, rows)
    col_ranges = get_ranges(sep_col_indices, cols)

    # Get marker value
    cell_vals = [grid[r][c] for r in range(rows) for c in range(cols)]
    val_counts = Counter(cell_vals)
    marker_val = [v for v in sorted(val_counts.keys()) if v != background and v != 0][0]

    # Count markers in each panel
    output = []
    for i, (r_start, r_end) in enumerate(row_ranges):
        row_list = []
        for j, (c_start, c_end) in enumerate(col_ranges):
            marker_count = 0
            for r in range(r_start, r_end + 1):
                for c in range(c_start, c_end + 1):
                    if grid[r][c] == marker_val:
                        marker_count += 1

            # Rule: count==1 → background, count==2 → 1
            if marker_count >= 1:
                if marker_count == 2:
                    row_list.append(1)
                else:
                    row_list.append(background)
            else:
                row_list.append(background)
        output.append(row_list)

    return output

